.animation-circle1 {
    animation: circles 2.5s linear infinite alternate
}

.animation-circle2 {
    animation: circles 2.5s 2s linear infinite alternate
}

.animation-circle3 {
    animation: circles2 2.5s linear infinite alternate
}

.animation-circle4 {
    animation: circles3 2.5s linear infinite alternate
}

.animation-twirl1 {
    animation: twirl1 60s linear infinite alternate
}

.animation-twirl2 {
    animation: twirl2 60s linear infinite alternate
}

.animation-puff-in {
    animation: puff-in 6s cubic-bezier(0.165,0.84,0.44,1) infinite
}

@keyframes circles {
    0% {
        transform: translate(0%,0%)
    }

    100% {
        transform: translate(0%,-20%)
    }
}

@keyframes circles2 {
    0% {
        transform: translate(0%,0%)
    }

    100% {
        transform: translate(10%,-20%)
    }
}

@keyframes circles3 {
    0% {
        transform: translate(0%,0%)
    }

    100% {
        transform: translate(-10%,20%)
    }
}

@keyframes upDown {
    0% {
        transform: translate(-50%,0)
    }

    100% {
        transform: translate(-50%,-20%)
    }
}

@keyframes twirl1 {
    0% {
        transform: translate(-50%,-50%) rotate(0deg)
    }

    100% {
        transform: translate(-50%,-50%) rotate(360deg)
    }
}

@keyframes twirl2 {
    0% {
        transform: rotate(360deg)
    }

    100% {
        transform: rotate(0deg)
    }
}

.mb-30 {
