}

.mb-40 {
    margin-bottom: 40px
}

@keyframes scroll {
    0% {
        transform: translateX(0)
    }

    100% {
        transform: translateX(calc(-100px * 11))
    }
}

@keyframes puff-in {
    0% {
        transform: scale(0.2) rotate(0);
        filter: blur(4px);
        opacity: 0;
        border-radius: 8px
    }

    50% {
        transform: scale(1) rotate(0);
        filter: blur(0px);
        opacity: 1;
        border-radius: 8px
    }

    100% {
        transform: scale(1.5) rotate(45deg);
        opacity: 0;
        border-radius: 50%
    }
}

.box-arrow-slick {
    margin-top: 4px
}

.box-arrow-slick .slick-dots-custom {
    margin: 0 16px
}

.box-arrow-slick .slick-arrow {
    cursor: pointer
}

.box-arrow-slick .slick-arrow i {
    display: flex;
    color: #f44438
}

.box-arrow-slick .slick-dots {
    display: flex
}

.box-arrow-slick .slick-dots li {
    display: flex;
    align-items: center;
    margin-right: 8px
}

.box-arrow-slick .slick-dots li:last-child {
    margin-right: 0
}

.box-arrow-slick .slick-dots .slick-active button {
    background-color: #f44438
}

.box-arrow-slick .slick-dots button {
    font-size: 0;
    padding: 0;
    width: 10px;
    height: 10px;
    border: 0;
    border-radius: 50%;
    background-color: #3c4358
}

.slick-track {
    display: flex !important
}

.slick-track .slick-slide {
    height: inherit !important
}

.slick-track .slick-slide>div,.slick-track .slick-slide .item {
    height: 100%
}

.custom-slick-dots .slick-dots {
    margin-top: 46px
}

.custom-slick-dots .slick-dots li,.custom-slick-dots .slick-dots button {
    width: 16px !important;
    height: 16px !important
}

.custom-slick-dots .slick-dots li {
    margin: 0px 16px
}

.custom-slick-dots .slick-dots li button {
    position: absolute;
    font-size: 0;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: #fff;
