.form-input-seo {
    position: relative
}

.form-input-seo label {
    top: 50%;
    transform: translateY(-50%);
    left: 15px;
    font-weight: 600;
    font-size: 12px;
    line-height: 1.2;
    padding: 0px 10px;
    user-select: none;
    pointer-events: none;
    background-color: #262e45;
    transition: top .25s ease-in-out
}

.form-input-seo textarea,.form-input-seo select,.form-input-seo input {
    background-color: #262e45;
    border: .5px solid #fff;
    border-radius: 5px;
    padding: 19px 25px;
    margin-bottom: 28px;
    font-weight: 600;
    font-size: 12px;
    line-height: 22px
}

.form-input-seo textarea:focus,.form-input-seo textarea:not(:placeholder-shown),.form-input-seo select:focus,.form-input-seo select:not(:placeholder-shown),.form-input-seo input:focus,.form-input-seo input:not(:placeholder-shown) {
    background-color: #262e45;
    color: #fff;
    border: .5px solid #fff
}

.form-input-seo textarea:focus+label,.form-input-seo textarea:not(:placeholder-shown)+label,.form-input-seo select:focus+label,.form-input-seo select:not(:placeholder-shown)+label,.form-input-seo input:focus+label,.form-input-seo input:not(:placeholder-shown)+label {
    top: 0
}

.form-input-seo textarea:-webkit-autofill,.form-input-seo select:-webkit-autofill,.form-input-seo input:-webkit-autofill {
    transition: background-color 600000s 0s,color 600000s 0s;
    color: #fff !important
}

.form-input-seo.textarea label {
    top: 10px;
    transform: translateY(0)
}

.form-input-seo.textarea textarea:focus+label,.form-input-seo.textarea textarea:not(:placeholder-shown)+label {
