    border-radius: 50px;
    padding: 20px;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    text-decoration: none;
    min-width: 200px;
}

.larksuite__btn-function {
    margin-right: 10px;
    margin-bottom: 10px;
    padding: 10px 20px;
    z-index: 111;
}

@media(max-width: 575px) {
    .larksuite__count::before {
        display: none;
    }

    .larksuite__count::after {
        display: none;
    }

    .larksuite__count {
        padding: 2.5rem 0;
    }

    .larksuite__btn-function {
        margin-right: 0;
    }
}

.larksuite .row {
    margin-left: 0 !important;
    margin-right: 0 !important;
    border-radius: 0;
}


